// ALL CODE BELOW WAS GENERATED BY CHATGPT, CODE NOT SPECIFIED AS "ADDED" or "CHANGED" IS THE FIRST ORIGINAL CODE

//for basic input/output, reading files, and strings
#include <fstream>
#include <iostream>
#include <string>

class Sudoku { //create the class used for the program. Create the puzzle board and methods used
private:   //private, only methods in Sudoku class can access the below:
    static constexpr int SIZE = 9;  //represents size of the board, set to 9                 ADDED
    static constexpr int BLOCK_SIZE = 3; //represents each block in the board (3x3)          ADDED
    int grid[SIZE][SIZE]{}; //creates the 9x9 board, each cell is 0                          CHANGED: replaced original [9][9] with variable SIZE
    int solutions = 0; //this variable will hold the count of solutions found

    //function that returns True or False. True if the number 1-9 will not be a duplicate
    bool canPlace(int row, int col, int value) const {    //pass a candidate number, the row it is in, and the column it is in   |   CHANGED: replaced 9 with SIZE
        for (int i = 0; i < SIZE; ++i) {    //iterate through the row and column of the cell
            if ((i != col && grid[row][i] == value) ||  //this checks the row of the cell, excluding the cell
                (i != row && grid[i][col] == value)) {  //checks column of the cell
                return false;  //returns False if a duplicate exists, which prevents the program from placing the value
            }
        }

        //CHANGED: replaced numbers with BLOCK_SIZE
        //equation used to check blocks of the sudoku board (3x3)
        int startRow = (row / BLOCK_SIZE) * BLOCK_SIZE; //finds the block's top row which can be 0, 3, or 6
        int startCol = (col / BLOCK_SIZE) * BLOCK_SIZE; //find the block's left column.
        for (int r = startRow; r < startRow + BLOCK_SIZE; ++r) { //go through the 3 rows of the block
            for (int c = startCol; c < startCol + BLOCK_SIZE; ++c) {  //go through the 3 columns of the block
                if ((r != row || c != col) && grid[r][c] == value) {  //check if there is a duplicate number in another cell (in the same block)
                    return false;  //returns False if the block has a duplicate number
                }
            }
        }
        return true; //all check work, returns True and can place the number there
    }

    //function returns True if successfully loads the file or False otherwise
    bool load(const std::string& filename) {  //pass filename
        std::ifstream file(filename); //try opening input file
        char cell; //holds one character

        //CHANGED: Both loops use SIZE instead of 9
        for (int row = 0; row < SIZE; ++row) {  //go through each row
            for (int col = 0; col < SIZE; ++col) { //go through each column in row
                if (!(file >> cell) ||       //this reads next non-whitespace character
                    (cell != '_' && (cell < '1' || cell > '9'))) {  //only accept the numbers 1-9 and the '_' for empty
                    return false; //this will stop the loading from an error from loading file
                }
                grid[row][col] = (cell == '_') ? 0 : cell - '0'; //store into cell into board, stores 0 if '_'
            }
        }
        if (file >> cell) { //checks and rejects any extra inputs after finished reading all cells
            return false;
        }
        return !file.bad(); //returns False if a serious reading error
    }

    //function displays the board
    void print() const { //void means does not return anything
        for (int row = 0; row < SIZE; ++row) {  //go through each row
            for (int col = 0; col < SIZE; ++col) { //go through each column
                char cell = (grid[row][col] == 0) //checks if the cell represents a blank
                                ? '_' : static_cast<char>('0' + grid[row][col]); //chooses '_' or the number
                //CHANGED: Both loops use SIZE instead of 9
                std::cout << cell << (col == SIZE - 1 ? '\n' : ' '); //prints the cell and space (newline if column is finished)
            }
        }
        std::cout << '\n'; //extra new line for the output file after board is printed
    }

    //CHANGED: now skips filled cells
    //searches every solution beginning at the position
    void solve(int position) {
        while (position < SIZE * SIZE &&   //check if it is within the bounds of the board
               grid[position / SIZE][position % SIZE] != 0) {  //continues while current cell is filled
            ++position; //moves to next cell without another recursive call
        }
        if (position == SIZE * SIZE) { //reached position 81, means every cell is filled            CHANGED: replaced 81 with SIZE*SIZE
            ++solutions; //adds one to the number of solutions
            std::cout << "Solution " << solutions << ":\n"; //prints the number of solutions found
            print(); //call previous print function to display the board
            return; //finishes call so previous calls check other possibilities
        }
        int row = position / SIZE; //converts the position to its row index with division           CHANGED: replaced 9 with SIZE
        int col = position % SIZE; //uses modulo to convert the position to its column index        CHANGED: replaced 9 with SIZE

        for (int value = 1; value <= SIZE; ++value) { //tries every number 1-9                      CHANGED: replaced 9 with SIZE
            if (canPlace(row, col, value)) { //continue if the number can be placed without unallowed repeats
                grid[row][col] = value; //temporarily fills the blank with the number
                solve(position + 1); //calls this function again to check remaining cells
                grid[row][col] = 0; //restore the blank so next number can be checked
            }
        }
    }


public: //main can call this function only, since it is public
    //this function gets the puzzle file, loads it, checks the clues/filled cells, and prints all possible solutions
    bool run(const std::string& filename) { //returns false if the input file cannot be loaded 
        std::cout << "Puzzle file: " << filename << '\n'; //output the file being used
        if (!load(filename)) {  //call load to check if it returned False
            std::cout << "Error: File missing or invalid puzzle format.\n\n";
            return false; //stops the processing of the file
        }
        std::cout << "Original puzzle:\n"; //output text
        print(); //this will display the board inputted before any solving
        bool valid = true; //assumes given clues/cells follow the sudoku rules

        //CHANGED: used SIZE instead of 9 in for loops
        for (int row = 0; row < SIZE; ++row) { //iterate through each row and check the given cells/clues
            for (int col = 0; col < SIZE; ++col) { //iterate through each cell in the row
                if (grid[row][col] != 0 && !canPlace(row, col, grid[row][col])) { //this checks each nonblank clue for any duplicates
                    valid = false; //will be False if the starting board breaks the sudoku rules
                }
            }
        }
        solutions = 0; //starts solution at 0 before solving

        //if starting board is valid, begin solving with recursive search at the first position out of 81
        if (valid) {
            solve(0);
        }

        //CHANGED: removed extra newline
        //if no solutions were found solving, output no solutions
        if (solutions == 0) { 
            std::cout << "No solution found\n";
        }

        //ADDED: prints total
        //if solutions found: output the solutions
        std::cout << "Solutions found: " << solutions << "\n\n";
        return true; //successful file loading
    }
};

//main function defined here using sudoku class
int main(int argc, char* argv[]) {

    //below displays error message if 0 or more than one file inputted
    if (argc != 2) { 
        std::cout << "Usage: " << argv[0] << " <filename>\n"; 
        return 1; 
    }

    Sudoku puzzle; //creates the sudoku object to create the board and use the methods

    return puzzle.run(argv[1]) ? 0 : 1; //use filename to the run() function which will read and begin using methods to solve
}
